 response = await leaseClient.acquireLease(durationInSeconds);\r\n    if (!response.leaseId) {\r\n      throw new Error(`Azure Storage did not return a lease ID for blob ${blobName}.`);\r\n    }\r\n\r\n    return {\r\n      leaseId: response.leaseId,\r\n      release: async () =\u003e {\r\n        await leaseClient.releaseLease();\r\n      },\r\n    };\r\n  }\r\n\r\n  private async uploadWithLease(\r\n    blockBlobClient: BlockBlobClient,\r\n    localFilePath: string,\r\n    options: UploadBlobOptions,\r\n  ): Promise\u003cvoid\u003e {\r\n    let leaseHandle: LeaseHandle | undefined;\r\n    let leaseId = options.leaseId;\r\n\r\n    if (!leaseId) {\r\n      leaseHandle = await this.acquireLease(blockBlobClient.name);\r\n      leaseId = leaseHandle.leaseId;\r\n    }\r\n\r\n    try {\r\n      await this.uploadStream(blockBlobClient, localFilePath, options, { leaseId });\r\n    } finally {\r\n      if (leaseHandle) {\r\n        await leaseHandle.release();\r\n      }\r\n    }\r\n  }\r\n\r\n  private async uploadStream(\r\n    blockBlobClient: BlockBlobClient,\r\n    localFilePath: string,\r\n    options: UploadBlobOptions,\r\n    conditions?: { ifNoneMatch?: string; leaseId?: string },\r\n  ): Promise\u003cvoid\u003e {\r\n    const readStream = createReadStream(localFilePath);\r\n\r\n    await blockBlobClient.uploadStream(\r\n      readStream,\r\n      options.bufferSize ?? DEFAULT_BUFFER_SIZE,\r\n      options.maxConcurrency ?? DEFAULT_MAX_CONCURRENCY,\r\n      {\r\n        metadata: options.metadata,\r\n        tags: options.tags,\r\n        conditions,\r\n      },\r\n    );\r\n  }\r\n\r\n  private async assertLocalFileExists(localFilePath: string): Promise\u003cvoid\u003e {\r\n    const fileStats = await stat(localFilePath);\r\n    if (!fileStats.isFile()) {\r\n      throw new Error(`Expected ${localFilePath} to be a file.`);\r\n    }\r\n  }\r\n\r\n  private isAlreadyExistsRace(error: unknown): boolean {\r\n    if (!(error instanceof RestError)) {\r\n      return false;\r\n    }\r\n\r\n    return error.statusCode === 409 || error.statusCode === 412;\r\n  }\r\n}\r\n\n```\n\n### src\\config.ts\n```\nimport { DefaultAzureCredential } from \"@azure/identity\";\r\nimport { AzureLogLevel, AzureLogger, setLogLevel } from \"@azure/logger\";\r\nimport {\r\n  BlobServiceClient,\r\n  StorageRetryPolicyType,\r\n  StoragePipelineOptions,\r\n} from \"@azure/storage-blob\";\r\n\r\nexport interface BlobStorageConfig {\r\n  endpoint: string;\r\n  containerName: string;\r\n  retryMaxTries: number;\r\n  retryDelayInMs: number;\r\n  retryMaxRetryDelayInMs: number;\r\n  logLevel: AzureLogLevel | \"none\";\r\n}\r\n\r\nconst supportedLogLevels = new Set\u003cBlobStorageConfig[\"logLevel\"]\u003e([\r\n  \"none\",\r\n  \"verbose\",\r\n  \"info\",\r\n  \"warning\",\r\n  \"error\",\r\n]);\r\n\r\nfunction requireEnv(env: NodeJS.ProcessEnv, key: string): string {\r\n  const value = env[key]?.trim();\r\n  if (!value) {\r\n    throw new Error(`Missing required environment variable: ${key}`);\r\n  }\r\n\r\n  return value;\r\n}\r\n\r\nfunction parsePositiveInteger(\r\n  env: NodeJS.ProcessEnv,\r\n  key: string,\r\n  defaultValue: number,\r\n): number {\r\n  const rawValue = env[key]?.trim();\r\n  if (!rawValue) {\r\n    return defaultValue;\r\n  }\r\n\r\n  const parsedValue = Number.parseInt(rawValue, 10);\r\n  if (!Number.isInteger(parsedValue) || parsedValue \u003c 1) {\r\n    throw new Error(`Environment variable ${key} must be a positive integer.`);\r\n  }\r\n\r\n  return parsedValue;\r\n}\r\n\r\nfunction parseLogLevel(env: NodeJS.ProcessEnv, key: string): BlobStorageConfig[\"logLevel\"] {\r\n  const rawValue = env[key]?.trim().toLowerCase() as BlobStorageConfig[\"logLevel\"] | undefined;\r\n  if (!rawValue) {\r\n    return \"warning\";\r\n  }\r\n\r\n  if (!supportedLogLevels.has(rawValue)) {\r\n    throw new Error(\r\n      `Environment variable ${key} must be one of: ${Array.from(supportedLogLevels).join(\", \")}.`,\r\n    );\r\n  }\r\n\r\n  return rawVa